chi = t**_sage_const_3  - QQ(_sage_const_55 )/_sage_const_64 *t**_sage_const_2  + QQ(_sage_const_1 )/_sage_const_2048 *t - QQ(_sage_const_1 )/(_sage_const_2 **_sage_const_20 )
print(f"\nCharacteristic polynomial: {chi}")
chi_roots = (_sage_const_2 **_sage_const_20  * chi).roots(QQbar, multiplicities=False)
